#!/usr/bin/env node
// Builds the two page bundles the extension loads, FROM THE SAME MODULES THE BOT RUNS (no fork):
//   vendor/vexa-page-capture.js  → globalThis.VexaPageCapture  = { installRemoteAudioHook, platforms }
//                                  each platform's PageCapture (@vexa/capture-codec's contract) from its own module:
//                                  zoom (@vexa/zoom-capture), google_meet (@vexa/gmeet-capture), teams
//                                  (@vexa/teams-capture over @vexa/mixed-capture-core's mixed lane); loaded in the
//                                  meeting tab, MAIN world, with the WebRTC hook (@vexa/mixed-capture-core)
//   vendor/vexa-capture-codec.js → globalThis.VexaCaptureCodec = { encodeAudioFrame, createSpeakerTimeline }
//                                  (@vexa/capture-codec; loaded in the panel tab with panel-capture.js)
// The outputs are generated files, committed so the folder loads unpacked as it is. Rebuild after any change
// to those modules:  VEXA_MODULES=<repo>/core/meetings/modules ESBUILD=<path to esbuild's package dir> node build-page-bundle.mjs
// (both default to this repo's layout and a resolvable `esbuild`). Each module's dist/ must be built first.
import path from 'node:path';
import fs from 'node:fs';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { execFileSync } from 'node:child_process';

const here = path.dirname(fileURLToPath(import.meta.url));
const MODULES = path.resolve(process.env.VEXA_MODULES || path.join(here, '..', '..', 'core', 'meetings', 'modules'));
const { build } = await import(process.env.ESBUILD ? pathToFileURL(path.join(process.env.ESBUILD, 'lib', 'main.js')).href : 'esbuild');

const entry = (pkg) => {
  const p = path.join(MODULES, pkg, 'dist', 'index.js');
  if (!fs.existsSync(p)) throw new Error(`missing ${p}: build @vexa/${pkg} first`);
  return JSON.stringify(p);
};
let source = 'unknown';
try { source = execFileSync('git', ['-C', MODULES, 'rev-parse', '--short=8', 'HEAD'], { encoding: 'utf8' }).trim(); } catch { /* not a checkout */ }

const outputs = [
  {
    file: 'vendor/vexa-page-capture.js',
    contents: `import { installRemoteAudioHook, createMixedLaneCapture, createSpeakerTimeline } from ${entry('mixed-capture-core')};
import { createZoomPageCapture } from ${entry('zoom-capture')};
import { createGmeetPageCapture } from ${entry('gmeet-capture')};
import { createTeamsPageCapture } from ${entry('teams-capture')};
// hook: the platform rides WebRTC (no per-participant media elements), so the hook must run at document_start
globalThis.VexaPageCapture = Object.freeze({
  installRemoteAudioHook,
  platforms: Object.freeze({
    zoom: Object.freeze({ create: createZoomPageCapture, hook: true }),
    google_meet: Object.freeze({ create: createGmeetPageCapture, hook: false }),
    // Teams' PageCapture takes the mixed lane as an injected dependency (its package has none)
    teams: Object.freeze({ create: (o) => createTeamsPageCapture({ ...o, createLane: createMixedLaneCapture, createTimeline: () => createSpeakerTimeline() }), hook: true }),
  }),
});`,
  },
  {
    file: 'vendor/vexa-capture-codec.js',
    contents: `import { encodeAudioFrame } from ${entry('capture-codec')};
import { createSpeakerTimeline } from ${entry('mixed-capture-core')};
// the panel names a tab's single stream with the same timeline Teams' PageCapture uses
globalThis.VexaCaptureCodec = Object.freeze({ encodeAudioFrame, createSpeakerTimeline });`,
  },
];

fs.mkdirSync(path.join(here, 'vendor'), { recursive: true });
for (const o of outputs) {
  await build({
    stdin: { contents: o.contents, resolveDir: MODULES, loader: 'js' },
    bundle: true, format: 'iife', platform: 'browser', target: 'chrome116',
    outfile: path.join(here, o.file), legalComments: 'none', logLevel: 'warning',
    banner: { js: `// GENERATED by build-page-bundle.mjs from core/meetings/modules at ${source}. Do not edit: rebuild.` },
  });
  console.log(`built ${o.file}`);
}
